<section class="mb-5 grid gap-4 sm:grid-cols-2 xl:grid-cols-4"><?php foreach ([['Cuentas',$resumen['cuentas'] ?? 0,'bi-receipt'],['Facturado','S/ '.number_format((float)($resumen['facturado'] ?? 0),2),'bi-cash-stack'],['Cobrado','S/ '.number_format((float)($resumen['cobrado'] ?? 0),2),'bi-check2-circle'],['Pendiente','S/ '.number_format((float)($resumen['pendiente'] ?? 0),2),'bi-hourglass-split']] as $kpi): ?><article class="rounded-2xl border border-slate-200 bg-white p-5 shadow-sm"><i class="bi <?= $kpi[2] ?> text-xl text-blue-600"></i><p class="mt-3 text-xs font-medium uppercase tracking-wide text-slate-500"><?= $kpi[0] ?></p><p class="mt-1 text-2xl font-bold"><?= $kpi[1] ?></p></article><?php endforeach; ?></section>
<section class="overflow-hidden rounded-2xl border border-slate-200 bg-white shadow-sm"><div class="overflow-x-auto"><table class="min-w-full text-left text-sm"><thead class="bg-slate-50 text-xs uppercase tracking-wide text-slate-500"><tr><th class="px-5 py-4">Alumno</th><th class="px-5 py-4">Concepto</th><th class="px-5 py-4">Vencimiento</th><th class="px-5 py-4">Importe</th><th class="px-5 py-4">Saldo</th><th class="px-5 py-4">Estado</th><th class="px-5 py-4"></th></tr></thead><tbody class="divide-y divide-slate-100"><?php foreach ($cuentas as $cuenta): ?><tr><td class="px-5 py-4 font-medium"><?= htmlspecialchars($cuenta['alumno']) ?><span class="block text-xs font-normal text-slate-500"><?= htmlspecialchars($cuenta['codigo_alumno'].' · '.$cuenta['seccion']) ?></span></td><td class="px-5 py-4"><?= htmlspecialchars($cuenta['concepto']) ?><span class="block text-xs text-slate-500"><?= htmlspecialchars($cuenta['apoderado'] ?: 'Sin apoderado') ?></span></td><td class="px-5 py-4"><?= $cuenta['fecha_vencimiento'] ?: '—' ?></td><td class="px-5 py-4">S/ <?= number_format((float)$cuenta['importe_original']-(float)$cuenta['descuento'],2) ?></td><td class="px-5 py-4 font-semibold">S/ <?= number_format((float)$cuenta['saldo'],2) ?></td><td class="px-5 py-4"><span class="rounded-full px-2 py-1 text-xs font-semibold <?= $cuenta['estado']==='PAGADA'?'bg-emerald-50 text-emerald-700':($cuenta['estado']==='PARCIAL'?'bg-amber-50 text-amber-700':'bg-red-50 text-red-700') ?>"><?= $cuenta['estado'] ?></span></td><td class="px-5 py-4"><?php if($cuenta['estado']!=='PAGADA' && $cuenta['estado']!=='ANULADA'): ?><button data-id="<?= $cuenta['id_cuenta'] ?>" data-alumno="<?= htmlspecialchars($cuenta['alumno'],ENT_QUOTES) ?>" data-saldo="<?= $cuenta['saldo'] ?>" onclick="abrirPago(this)" class="text-sm font-semibold text-blue-600">Registrar pago</button><?php endif; ?></td></tr><?php endforeach; ?><?php if (!$cuentas): ?><tr><td colspan="7" class="px-5 py-12 text-center text-slate-500">No hay cuentas generadas para este mes.</td></tr><?php endif; ?></tbody></table></div></section>
<div id="modal-generar" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-12 max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between"><div><h2 class="text-lg font-bold">Generar cuentas</h2><p class="text-sm text-slate-500">Crea mensualidades para todas las matrículas activas.</p></div><button onclick="this.closest('.fixed').classList.add('hidden')" class="p-2"><i class="bi bi-x-lg"></i></button></div><form method="post" action="index.php?url=cobros_generar" class="mt-5 grid gap-4"><?= campoCsrf() ?><label class="form-label">Mes de cobro<input type="month" required name="mes" value="<?= htmlspecialchars($mes) ?>" class="form-input"></label><label class="form-label">Periodo académico<select required name="id_periodo_academico" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['periodos'] as $p): ?><option value="<?= $p['id_periodo_academico'] ?>"><?= htmlspecialchars($p['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Concepto<select required name="id_concepto_cobro" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['conceptos'] as $c): ?><option value="<?= $c['id_concepto_cobro'] ?>"><?= htmlspecialchars($c['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Fecha de vencimiento <span class="font-normal text-slate-400">(opcional)</span><input type="date" name="fecha_vencimiento" class="form-input"></label><button class="rounded-xl bg-blue-600 px-4 py-2.5 text-sm font-semibold text-white">Generar</button></form></div></div>
<div id="modal-pago" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-12 max-w-lg rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between"><div><h2 class="text-lg font-bold">Registrar pago</h2><p id="pago-alumno" class="text-sm text-slate-500"></p></div><button onclick="this.closest('.fixed').classList.add('hidden')" class="p-2"><i class="bi bi-x-lg"></i></button></div><form method="post" action="index.php?url=cobros_pagar" class="mt-5 grid gap-4"><?= campoCsrf() ?><input type="hidden" name="mes" value="<?= htmlspecialchars($mes) ?>"><input id="pago-cuenta" type="hidden" name="id_cuenta"><label class="form-label">Importe a pagar<input id="pago-importe" required min="0.01" step="0.01" type="number" name="importe" class="form-input"></label><label class="form-label">Medio de pago<select name="medio_pago" class="form-input"><option>EFECTIVO</option><option>TRANSFERENCIA</option><option>YAPE</option><option>PLIN</option><option>OTRO</option></select></label><label class="form-label">Observación <span class="font-normal text-slate-400">(opcional)</span><input name="observacion" maxlength="250" class="form-input"></label><button class="rounded-xl bg-emerald-600 px-4 py-2.5 text-sm font-semibold text-white">Confirmar pago</button></form></div></div>
<div id="modal-tarifa" class="fixed inset-0 z-[60] hidden overflow-y-auto bg-slate-900/45 p-4"><div class="mx-auto mt-8 max-w-2xl rounded-2xl bg-white p-6 shadow-2xl"><div class="flex justify-between"><div><h2 class="text-lg font-bold">Conceptos y tarifas</h2><p class="text-sm text-slate-500">La tarifa por grado tiene prioridad sobre la tarifa general.</p></div><button onclick="this.closest('.fixed').classList.add('hidden')" class="p-2"><i class="bi bi-x-lg"></i></button></div><div class="mt-5 grid gap-6 md:grid-cols-2"><form method="post" action="index.php?url=cobros_configurar" class="grid gap-3 rounded-xl bg-slate-50 p-4"><?= campoCsrf() ?><input type="hidden" name="accion" value="concepto"><h3 class="font-bold">Nuevo concepto</h3><label class="form-label">Nombre<input required name="nombre" class="form-input"></label><label class="form-label">Tipo<select name="tipo" class="form-input"><?php foreach(['MATRICULA','MENSUALIDAD','TALLER','CUOTA','OTRO'] as $tipo): ?><option><?= $tipo ?></option><?php endforeach; ?></select></label><label class="flex gap-2 text-sm"><input type="checkbox" name="admite_parcial" checked> Admite pagos parciales</label><button class="rounded-xl bg-slate-800 px-4 py-2 text-sm font-semibold text-white">Crear concepto</button></form><form method="post" action="index.php?url=cobros_configurar" class="grid gap-3 rounded-xl bg-slate-50 p-4"><?= campoCsrf() ?><input type="hidden" name="accion" value="tarifa"><h3 class="font-bold">Nueva tarifa</h3><label class="form-label">Concepto<select required name="id_concepto_cobro" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['conceptos'] as $c): ?><option value="<?= $c['id_concepto_cobro'] ?>"><?= htmlspecialchars($c['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Periodo<select required name="id_periodo_academico" class="form-input"><option value="">Seleccione</option><?php foreach($opciones['periodos'] as $p): ?><option value="<?= $p['id_periodo_academico'] ?>"><?= htmlspecialchars($p['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Grado <span class="font-normal text-slate-400">(general si se omite)</span><select name="id_grado" class="form-input"><option value="">Tarifa general</option><?php foreach($grados as $g): ?><option value="<?= $g['id_grado'] ?>"><?= htmlspecialchars($g['nombre']) ?></option><?php endforeach; ?></select></label><label class="form-label">Importe<input required min="0" step="0.01" type="number" name="importe" class="form-input"></label><label class="form-label">Vigencia desde<input required type="date" name="vigencia_inicio" value="<?= date('Y-m-d') ?>" class="form-input"></label><label class="form-label">Vigencia hasta <span class="font-normal text-slate-400">(opcional)</span><input type="date" name="vigencia_fin" class="form-input"></label><button class="rounded-xl bg-blue-600 px-4 py-2 text-sm font-semibold text-white">Registrar tarifa</button></form></div></div></div>
<script>function abrirPago(b){document.getElementById('pago-cuenta').value=b.dataset.id;document.getElementById('pago-alumno').textContent=b.dataset.alumno+' · saldo S/ '+Number(b.dataset.saldo).toFixed(2);document.getElementById('pago-importe').value=Number(b.dataset.saldo).toFixed(2);document.getElementById('pago-importe').max=b.dataset.saldo;document.getElementById('modal-pago').classList.remove('hidden');}</script>
